def page(name,title,body,js='',desc=''):
    scripts=''.join(f'<script src="js/{x}.js"></script>' for x in ['app']+js.split() if x)
    s=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b0d0f"><title>{title} — SOC Atlas</title><link rel="stylesheet" href="css/style.css"></head><body data-page="{name}">{header}<main class="wrap">{body}</main>{footer}{scripts}</body></html>'''
    (p/f'{name}.html').write_text(s,encoding='utf-8')
def head(breadcrumb,eyebrow,h1,desc,tags=''):
    return f'''<div class="page-head"><div class="breadcrumbs"><a href="index.html">Обзор</a> / {breadcrumb}</div><div class="eyebrow">{eyebrow}</div><h1>{h1}</h1><p>{desc}</p>{f'<div class="page-tags">{tags}</div>' if tags else ''}</div>'''

