# academy
academy=head('Обучение','Операционное мышление','Не запоминать названия.<br><span class="text-accent">Понимать процесс.</span>','Ключевые понятия SOC-аналитика с примерами и логикой решений. Используй страницу как справочник перед практикой.')
concepts=[('01','Что делает SOC L1?','Отслеживает алерты, проверяет контекст, собирает первичные доказательства, классифицирует сработку и документирует либо передаёт инцидент по процедуре. L1 не должен выходить за пределы своих полномочий.','Хороший результат — обоснованное, воспроизводимое решение с понятным следующим шагом.'),('02','Событие, алерт и инцидент','Событие — запись о действии. Алерт — сигнал по правилу или модели. Инцидент — достаточно обоснованное нарушение безопасности, требующее обработки. Алерт может оказаться легитимной активностью.','Не называй каждый алерт атакой. Уточни, что наблюдалось, каким источником и при каких условиях.'),('03','Evidence vs. hypothesis','Факт: за короткий интервал были неудачные входы для нескольких аккаунтов с одного источника. Гипотеза: это может быть password spraying. Вывод требует проверки альтернатив и контекста.','Разделяй наблюдения → интерпретацию → проверку → вывод → ограничения.'),('04','Severity, confidence, priority','Severity — тяжесть потенциального события. Confidence — насколько сигнал поддержан доказательствами. Priority — очередность действий с учётом воздействия, критичности актива и сроков.','Высокая тяжесть при низкой уверенности может требовать срочной проверки, но не автоматического обвинения.'),('05','Что включить в тикет','Резюме, время и часовой пояс, затронутые хосты/учётные записи, источники телеметрии, ключевые события, проверки, статус, scope, неизвестные данные и следующий шаг.','Пиши так, чтобы коллега из другой смены мог продолжить расследование без устного пересказа.'),('06','Когда эскалировать','Следуй runbook. Эскалация важна при возможной компрометации привилегированного аккаунта, исполнении кода, критичном активе, широком scope или нехватке полномочий.','Эскалация — контроль риска и передача работы подходящей роли.')]
academy+='''<div class="grid two">'''+''.join(f'<article class="card reveal"><div class="card-icon">{n}</div><h3>{t}</h3><p>{d}</p><div class="highlight-block">{h}</div></article>' for n,t,d,h in concepts)+'''</div><section class="section"><div class="section-head"><div><div class="eyebrow">Универсальный workflow</div><h2>Семь шагов разбора алерта</h2></div></div><div class="grid">'''+''.join(f'<div class="card reveal"><div class="card-icon">{i:02}</div><h3>{t}</h3><p>{d}</p></div>' for i,(t,d) in enumerate([('Прочитать сигнал','Правило, severity, время, актив, пользователь и источник.'),('Проверить качество','Диапазон времени, дубли, задержки, timezone и поля.'),('Добавить контекст','События до и после, baseline, критичность актива.'),('Сформировать гипотезу','Что объясняет наблюдения? Какие альтернативы есть?'),('Проверить','Запросы в SIEM, endpoint, DNS/proxy и авторизация.'),('Принять решение','Закрыть по критерию, продолжить сбор данных или эскалировать.'),('Документировать','Факты, вывод, ограничения, действия и следующий шаг.') ,],1))+'''</div></section><div class="notice warn"><strong>Безопасная практика:</strong> вся телеметрия SOC Atlas синтетическая. Не анализируй чужой трафик и не воздействуй на системы без явного разрешения.</div>'''
page('academy','Учебный центр',academy)
