body+='''<div class="notice"><strong>Синтаксис поиска:</strong> можно искать обычные слова или применять <code>user:a.ivanov</code>, <code>source:auth</code>, <code>severity:high</code>, <code>category:endpoint</code>, <code>type:AUTH_FAILURE</code>. Это учебный parser, не полный SPL или KQL.</div><div class="stats-row" style="margin-bottom:17px"><div class="stat"><div class="stat-value" id="siem-total">12</div><div class="stat-label">Событий</div></div><div class="stat"><div class="stat-value text-red" id="siem-high">0</div><div class="stat-label">High / Critical</div></div><div class="stat"><div class="stat-value" id="siem-shown">12</div><div class="stat-label">В выборке</div></div><div class="stat"><div class="stat-value" id="siem-review">0</div><div class="stat-label">Помечено к обзору</div></div></div><div class="toolbar"><input class="field grow" id="siem-query" placeholder="Поиск: user:a.ivanov severity:high"><select class="field select" id="siem-category"><option value="all">Все источники</option><option value="auth">Authentication</option><option value="endpoint">Endpoint</option><option value="dns">DNS</option><option value="network">Network</option><option value="proxy">Proxy</option></select><select class="field select" id="siem-severity"><option value="all">Все уровни</option><option value="critical">Critical</option><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select><button class="btn primary small" id="siem-search">Поиск</button><button class="btn small" id="siem-reset">Сброс</button></div><div class="lab-layout"><section class="lab-panel"><div class="lab-panel-head"><h3>Event stream</h3><span id="siem-count">12 RESULTS</span></div><div class="table-wrap" style="border:0;border-radius:0"><table class="table"><thead><tr><th>Time</th><th>Event ID</th><th>Source</th><th>Type</th><th>User</th><th>Severity</th></tr></thead><tbody id="siem-rows"></tbody></table></div><div id="siem-empty" class="empty-state hidden">Нет событий для этих фильтров.</div></section><aside><div class="lab-panel"><div class="lab-panel-head"><h3>Event detail</h3><span id="detail-eventid">SELECT EVENT</span></div><div class="lab-panel-body alert-detail" id="siem-detail"><div class="empty-state">Выбери событие слева.</div></div></div><div class="lab-panel" style="margin-top:14px"><div class="lab-panel-head"><h3>Query examples</h3><span>CLICK TO USE</span></div><div class="lab-panel-body"><div class="query-examples"><button data-sq="severity:high">severity:high</button><button data-sq="user:a.ivanov">user:a.ivanov</button><button data-sq="type:AUTH_FAILURE">type:AUTH_FAILURE</button><button data-sq="powershell">powershell</button><button data-sq="category:dns">category:dns</button></div><div class="lesson-note"><span>↳</span><p><b>Запрос — не вывод.</b> Сначала посмотри исходные строки, затем проверь, какие данные поддерживают гипотезу, а какие нужны дополнительно.</p></div></div></div></aside></div>'''
page('siem','Mini SIEM',body,'siem-data siem')
